
import { createClient } from "npm:@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers":
        "authorization, x-client-info, apikey, content-type",
          "Access-Control-Allow-Methods": "POST, OPTIONS",
          };

          const json = (data: unknown, status = 200) =>
            new Response(JSON.stringify(data), {
                status,
                    headers: { ...corsHeaders, "Content-Type": "application/json" },
                      });

                      Deno.serve(async (req: Request) => {
                        if (req.method === "OPTIONS") {
                            return new Response("ok", { headers: corsHeaders });
                              }

                                if (req.method !== "POST") {
                                    return json({ error: "POST requests only." }, 405);
                                      }

                                        try {
                                            const url = Deno.env.get("SUPABASE_URL");
                                                const anonKey = Deno.env.get("SUPABASE_ANON_KEY");
                                                    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

                                                        if (!url || !anonKey || !serviceKey) {
                                                              return json({ error: "Server configuration is incomplete." }, 500);
                                                                  }

                                                                      const body = await req.json();
                                                                          const action = String(body.action ?? "");
                                                                              const identifier = String(body.identifier ?? "").trim();
                                                                                  const password = String(body.password ?? "");

                                                                                      const publicClient = createClient(url, anonKey, {
                                                                                            auth: { persistSession: false, autoRefreshToken: false },
                                                                                                });

                                                                                                    const admin = createClient(url, serviceKey, {
                                                                                                          auth: { persistSession: false, autoRefreshToken: false },
                                                                                                              });

                                                                                                                  if (action === "login") {
                                                                                                                        if (!identifier || !password) {
                                                                                                                                return json({ error: "Enter your username or email and password." }, 400);
                                                                                                                                      }

                                                                                                                                            let email = identifier;

                                                                                                                                                  if (!identifier.includes("@")) {
                                                                                                                                                          const { data: profile, error } = await admin
                                                                                                                                                                    .from("profiles")
                                                                                                                                                                              .select("id")
                                                                                                                                                                                        .ilike("username", identifier)
                                                                                                                                                                                                  .maybeSingle();

                                                                                                                                                                                                          if (error || !profile) {
                                                                                                                                                                                                                    return json({ error: "Invalid username/email or password." }, 401);
                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                    const { data: userData, error: userError } =
                                                                                                                                                                                                                                              await admin.auth.admin.getUserById(profile.id);

                                                                                                                                                                                                                                                      if (userError || !userData.user?.email) {
                                                                                                                                                                                                                                                                return json({ error: "Invalid username/email or password." }, 401);
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                email = userData.user.email;
                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                            const { data, error } = await publicClient.auth.signInWithPassword({
                                                                                                                                                                                                                                                                                                    email,
                                                                                                                                                                                                                                                                                                            password,
                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                        if (error || !data.session) {
                                                                                                                                                                                                                                                                                                                                return json({ error: "Invalid username/email or password." }, 401);
                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                            return json({ session: data.session, user: data.user });
                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                    if (action === "forgot_password") {
                                                                                                                                                                                                                                                                                                                                                          if (!identifier || !identifier.includes("@")) {
                                                                                                                                                                                                                                                                                                                                                                  return json({ error: "Enter your registered email address." }, 400);
                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                              const siteUrl =
                                                                                                                                                                                                                                                                                                                                                                                      Deno.env.get("SITE_URL") ??
                                                                                                                                                                                                                                                                                                                                                                                              "https://goofytechwiz.github.io/TikNation/";

                                                                                                                                                                                                                                                                                                                                                                                                    const { error } = await publicClient.auth.resetPasswordForEmail(
                                                                                                                                                                                                                                                                                                                                                                                                            identifier,
                                                                                                                                                                                                                                                                                                                                                                                                                    { redirectTo: siteUrl },
                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                if (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                        console.error("Password reset request failed:", error.message);
                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                    return json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                            message:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "If an account exists for that email, password-reset instructions will be sent.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (action === "forgot_username") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!identifier || !identifier.includes("@")) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return json({ error: "Enter your registered email address." }, 400);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const resendKey = Deno.env.get("RESEND_API_KEY");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const fromEmail = Deno.env.get("RECOVERY_FROM_EMAIL");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!resendKey || !fromEmail) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return json({ error: "Username recovery email is not configured yet." }, 503);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              let matchedUser: { id: string; email?: string } | null = null;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    for (let page = 1; page <= 100; page++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const { data, error } = await admin.auth.admin.listUsers({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      page,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                perPage: 1000,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          console.error("Account lookup failed:", error.message);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return json({ error: "Recovery is temporarily unavailable." }, 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    matchedUser =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              data.users.find(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          (user) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        user.email?.toLowerCase() === identifier.toLowerCase(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ) ?? null;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (matchedUser || data.users.length < 1000) break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (matchedUser) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const { data: profile } = await admin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        .from("profiles")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .select("username")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .eq("id", matchedUser.id)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      .maybeSingle();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (profile?.username) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const response = await fetch("https://api.resend.com/emails", {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    method: "POST",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                headers: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Authorization: `Bearer ${resendKey}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Content-Type": "application/json",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    body: JSON.stringify({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  from: fromEmail,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                to: [identifier],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              subject: "Your TikNation username",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            text: `Your TikNation username is: ${profile.username}\n\nIf you did not request this email, you can ignore it.`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!response.ok) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.error("Username recovery email could not be sent.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return json({ error: "Recovery email could not be sent. Please try again later." }, 502);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          message:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "If an account exists for that email, username recovery instructions will be sent.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return json({ error: "Unknown action." }, 400);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.error("TikNation backend request failed:", error);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return json({ error: "Something went wrong. Please try again." }, 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              